def validate_PhysicsCollection(value: PhysicsCollection) -> None:
    if isinstance(value, PhysicsCollectionGroups):
        pass
    elif isinstance(value, PhysicsCollectionInputs):
        _check_string(value.group_id)
    elif isinstance(value, PhysicsCollectionOutputs):
        _check_string(value.group_id)
    elif isinstance(value, PhysicsCollectionNodes):
        _check_string(value.group_id)
    else:
        raise TypeError("Expected PhysicsCollection")

def encode_PhysicsCollection(value: PhysicsCollection) -> object:
    if isinstance(value, PhysicsCollectionGroups):
        return {'kind': 'groups', **cast(Mapping[str, object], {})}
    elif isinstance(value, PhysicsCollectionInputs):
        return {'kind': 'inputs', **cast(Mapping[str, object], {'group_id': value.group_id})}
    elif isinstance(value, PhysicsCollectionOutputs):
        return {'kind': 'outputs', **cast(Mapping[str, object], {'group_id': value.group_id})}
    elif isinstance(value, PhysicsCollectionNodes):
        return {'kind': 'nodes', **cast(Mapping[str, object], {'group_id': value.group_id})}
    raise TypeError("Expected PhysicsCollection")

def read_PhysicsCollection(value: object) -> PhysicsCollection:
    if isinstance(value, (PhysicsCollectionGroups, PhysicsCollectionInputs, PhysicsCollectionOutputs, PhysicsCollectionNodes,)): return value
    r = record(value)
    tag = string(r['kind'])
    if tag == 'groups':
        return PhysicsCollectionGroups()
    elif tag == 'inputs':
        f = record(r)
        return PhysicsCollectionInputs(group_id=string(f['group_id']))
    elif tag == 'outputs':
        f = record(r)
        return PhysicsCollectionOutputs(group_id=string(f['group_id']))
    elif tag == 'nodes':
        f = record(r)
        return PhysicsCollectionNodes(group_id=string(f['group_id']))
    raise ValueError("Unknown PhysicsCollection variant")

def validate_PhysicsRigSnapshot(value: PhysicsRigSnapshot) -> None:
    if not isinstance(value, PhysicsRigSnapshot):
        raise TypeError("Expected PhysicsRigSnapshot")
    _check_string(value.id)
    if not isinstance(value.input_ids, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.input_ids:
        _check_string(v0)
    if not isinstance(value.output_ids, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.output_ids:
        _check_string(v0)
    if not isinstance(value.node_ids, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.node_ids:
        _check_string(v0)
    if not isinstance(value.particles, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.particles:
        if not isinstance(v0, tuple):
            raise TypeError("Expected an immutable tuple")
        if len(v0) != 2:
            raise ValueError("Invalid fixed array length")
        for v1 in v0:
            _check_f32(v1)
    _check_f32(value.input_angle)
    if not isinstance(value.inputs, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.inputs:
        _check_f32(v0)
    if not isinstance(value.outputs, tuple):
        raise TypeError("Expected an immutable tuple")
    for v0 in value.outputs:
        if v0 is not None:
            validate_PhysicsOutputSnapshot(v0)

def encode_PhysicsRigSnapshot(value: PhysicsRigSnapshot) -> object:
    return {'id': value.id, 'input_ids': [v0 for v0 in value.input_ids], 'output_ids': [v0 for v0 in value.output_ids], 'node_ids': [v0 for v0 in value.node_ids], 'particles': [[v1 for v1 in v0] for v0 in value.particles], 'input_angle': value.input_angle, 'inputs': [v0 for v0 in value.inputs], 'outputs': [None if v0 is None else encode_PhysicsOutputSnapshot(v0) for v0 in value.outputs]}

